        let interfaceName = Interop.text "CSSTransformComponent runtime interface" (fun buffer capacity length -> NativeDom.rv_dom_css_transform_component_get_interface_name(handle, buffer, capacity, length))
        let wrapped: NativeObject =
            match interfaceName with
            | "CSSMatrixComponent" -> CSSMatrixComponentObject(session, handle)
            | "CSSPerspective" -> CSSPerspectiveObject(session, handle)
            | "CSSRotate" -> CSSRotateObject(session, handle)
            | "CSSScale" -> CSSScaleObject(session, handle)
            | "CSSSkew" -> CSSSkewObject(session, handle)
            | "CSSSkewX" -> CSSSkewXObject(session, handle)
            | "CSSSkewY" -> CSSSkewYObject(session, handle)
            | "CSSTranslate" -> CSSTranslateObject(session, handle)
            | "CSSTransformComponent" -> CSSTransformComponentObject(session, handle)
            | name -> invalidOp ("Unknown CSSTransformComponent runtime interface: " + name)
        wrapped

    static member Event(session: Session, handle: nativeint) : NativeObject =
        if Native.rv_abi_has "dom-type-query:Event" = 0 then Interop.unsupported<unit> "Event runtime interface"
